#include <vector>
#include <unordered_set>

using namespace std;

class Solution {
public:
    int uniqueXorTriplets(vector<int>& nums) {
        int n = nums.size();
        unordered_set<int> pairs;
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                pairs.insert(nums[i] ^ nums[j]);
            }
        }
        unordered_set<int> triplets;
        for (int p : pairs) {
            for (int x : nums) {
                triplets.insert(p ^ x);
            }
        }
        return triplets.size();
    }
};

import java.util.*;

class Solution {
    public int uniqueXorTriplets(int[] nums) {
        int n = nums.length;
        Set<Integer> pairs = new HashSet<>();
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                pairs.add(nums[i] ^ nums[j]);
            }
        }
        Set<Integer> triplets = new HashSet<>();
        for (int p : pairs) {
            for (int x : nums) {
                triplets.add(p ^ x);
            }
        }
        return triplets.size();
    }
}

